-- Respaldo de las plantillas de Autorización de Descuento por Nómina ANTES del rediseño
-- (migraciones/2026-11-26_plantillas_descuento_nomina_diseno.sql). Para volver atrás, ejecutar este archivo.

UPDATE Maestro_Plantillas SET version = 1, version_formato = '1', fecha_version = NULL, ultima_actualizacion = NOW(), contenido_html = '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <style>\n    body {\n      font-family: Arial, sans-serif;\n      font-size: 10pt;\n      line-height: 1.6;\n      color: #333;\n      margin: 40px;\n      padding: 0;\n    }\n    .header-table {\n      width: 100%;\n      border-collapse: collapse;\n      margin-bottom: 30px;\n    }\n    .header-table td {\n      border: 1px solid #333;\n      padding: 8px 12px;\n      vertical-align: middle;\n      text-align: center;\n    }\n    .logo-cell {\n      width: 25%;\n    }\n    .logo-cell img {\n      max-width: 130px;\n      height: auto;\n    }\n    .title-cell {\n      width: 50%;\n      font-weight: bold;\n      font-size: 11pt;\n      text-transform: uppercase;\n    }\n    .meta-cell {\n      width: 25%;\n      font-size: 8pt;\n      text-align: left;\n      line-height: 1.4;\n    }\n    h2 {\n      font-size: 12pt;\n      text-align: center;\n      margin-top: 20px;\n      margin-bottom: 20px;\n      text-transform: uppercase;\n      text-decoration: underline;\n    }\n    .content-p {\n      text-align: justify;\n      margin-bottom: 16px;\n      text-indent: 30px;\n    }\n    .signature-container {\n      width: 100%;\n      margin-top: 60px;\n      page-break-inside: avoid;\n    }\n    .signature-block {\n      width: 250px;\n      margin: 0 auto;\n      text-align: center;\n      font-size: 9pt;\n      page-break-inside: avoid;\n    }\n    .signature-line {\n      width: 100%;\n      border-top: 1px solid #333;\n      margin-top: 5px;\n      padding-top: 5px;\n      font-weight: bold;\n    }\n    .signature-img-wrapper {\n      height: 80px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      margin-bottom: 5px;\n    }\n    .signature-img-wrapper img {\n      max-height: 75px;\n      max-width: 100%;\n    }\n  </style>\n</head>\n<body>\n  <table class=\"header-table\">\n    <tr>\n      <td class=\"logo-cell\">\n        <img src=\"https://storage.googleapis.com/logyser-recibo-public/logo.png\" alt=\"LOG&SER\">\n      </td>\n      <td class=\"title-cell\">\n        Autorización Anticipada de Descuento por Nómina\n      </td>\n      <td class=\"meta-cell\">\n        <strong>Versión:</strong> 1<br>\n        <strong>Página:</strong> 1 de 1<br>\n        <strong>Fecha:</strong> {{fecha}}\n      </td>\n    </tr>\n  </table>\n\n  <h2>AUTORIZACIÓN ANTICIPADA DE DESCUENTO POR NÓMINA</h2>\n\n  <p style=\"margin-bottom: 20px; font-weight: bold;\">SEÑORES: APOYO LOGÍSTICO Y OPERATIVO SAS<br>NIT: 900.318.733-1</p>\n\n  <p class=\"content-p\">\n    Yo, <strong>{{nombre_trabajador}}</strong>, mayor de edad, identificado con documento de identidad No. <strong>{{identificacion}}</strong>, en mi calidad de trabajador con el cargo de <strong>{{cargo}}</strong> de la empresa <strong>APOYO LOGÍSTICO Y OPERATIVO SAS</strong>, suscribo el presente documento de manera libre, voluntaria y expresa.\n  </p>\n\n  <p class=\"content-p\">\n    Por medio del presente, <strong>AUTORIZO</strong> de manera expresa, anticipada e irrevocable a la empresa para que, en caso de que se presente cualquier daño, pérdida, deterioro o perjuicio causado por mi acción, omisión, negligencia o imprudencia en los equipos, herramientas, mercancía, vehículos, instalaciones o cualquier bien propiedad de la empresa o de terceros bajo responsabilidad de la misma, proceda a realizar el descuento correspondiente a dichos daños de mi salario, prestaciones sociales, indemnizaciones, bonificaciones o cualquier suma de dinero que se me deba por concepto de mi relación laboral.\n  </p>\n\n  <p class=\"content-p\">\n    Esta autorización se firma simultáneamente con el contrato de trabajo como garantía ante eventuales siniestros futuros. El valor a descontar será equivalente al costo de reparación o reposición del bien afectado, previa comunicación escrita por parte de la empresa donde se evidencie la responsabilidad y el valor del perjuicio.\n  </p>\n\n  <p class=\"content-p\">\n    En caso de que el valor del daño supere el salario mensual, autorizo a que el descuento se realice en cuotas mensuales sucesivas hasta completar el valor total adeudado. Asimismo, autorizo que, si al momento de ocurrir el siniestro o posteriormente, se llegare a terminar mi contrato de trabajo por cualquier causa, el saldo pendiente de dicha obligación sea deducido de mi liquidación final de prestaciones sociales y salarios pendientes.\n  </p>\n\n  <p class=\"content-p\" style=\"margin-top: 30px;\">\n    Dado en <strong>{{ciudad}}</strong>, a los <strong>{{dia}}</strong> días del mes de <strong>{{mes}}</strong> del año <strong>{{anio}}</strong>.\n  </p>\n\n  <div class=\"signature-container\">\n    <div class=\"signature-block\">\n      <div class=\"signature-img-wrapper\">\n        {{firma_trabajador}}\n      </div>\n      <div class=\"signature-line\">\n        Firma del Trabajador<br>\n        <span style=\"font-weight: normal; font-size: 8.5pt;\">Documento: {{identificacion}}</span>\n      </div>\n    </div>\n  </div>\n</body>\n</html>'
WHERE id_plantilla = 10 AND nombre_proceso = 'descuento_anticipado';

UPDATE Maestro_Plantillas SET version = 1, version_formato = '1', fecha_version = NULL, ultima_actualizacion = NOW(), contenido_html = '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <style>\n    body {\n      font-family: Arial, sans-serif;\n      font-size: 10.5pt;\n      line-height: 1.6;\n      color: #333;\n      margin: 40px;\n      padding: 0;\n    }\n    .header-table {\n      width: 100%;\n      border-collapse: collapse;\n      margin-bottom: 30px;\n    }\n    .header-table td {\n      border: 1px solid #333;\n      padding: 8px 12px;\n      vertical-align: middle;\n      text-align: center;\n    }\n    .logo-cell {\n      width: 25%;\n    }\n    .logo-cell img {\n      max-width: 130px;\n      height: auto;\n    }\n    .title-cell {\n      width: 50%;\n      font-weight: bold;\n      font-size: 11pt;\n      text-transform: uppercase;\n    }\n    .meta-cell {\n      width: 25%;\n      font-size: 8pt;\n      text-align: left;\n      line-height: 1.4;\n    }\n    h2 {\n      font-size: 12pt;\n      text-align: center;\n      margin-top: 20px;\n      margin-bottom: 20px;\n      text-transform: uppercase;\n      text-decoration: underline;\n    }\n    .content-p {\n      text-align: justify;\n      margin-bottom: 20px;\n      text-indent: 30px;\n    }\n    .signature-container {\n      width: 100%;\n      margin-top: 60px;\n      page-break-inside: avoid;\n    }\n    .signature-block {\n      width: 250px;\n      margin: 0 auto;\n      text-align: center;\n      font-size: 9pt;\n      page-break-inside: avoid;\n    }\n    .signature-line {\n      width: 100%;\n      border-top: 1px solid #333;\n      margin-top: 5px;\n      padding-top: 5px;\n      font-weight: bold;\n    }\n    .signature-img-wrapper {\n      height: 80px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      margin-bottom: 5px;\n    }\n    .signature-img-wrapper img {\n      max-height: 75px;\n      max-width: 100%;\n    }\n  </style>\n</head>\n<body>\n  <table class=\"header-table\">\n    <tr>\n      <td class=\"logo-cell\">\n        <img src=\"https://storage.googleapis.com/logyser-recibo-public/logo.png\" alt=\"LOG&SER\">\n      </td>\n      <td class=\"title-cell\">\n        Formato Autorización de Descuento por Nómina\n      </td>\n      <td class=\"meta-cell\">\n        <strong>Versión:</strong> 1<br>\n        <strong>Página:</strong> 1 de 1<br>\n        <strong>Fecha:</strong> {{fecha}}\n      </td>\n    </tr>\n  </table>\n\n  <h2>FORMATO AUTORIZACIÓN DE DESCUENTO POR NÓMINA</h2>\n\n  <p style=\"margin-bottom: 20px; font-weight: bold;\">SEÑORES: APOYO LOGÍSTICO Y OPERATIVO SAS<br>NIT: 900.318.733-1</p>\n  \n  <p style=\"margin-bottom: 25px; font-weight: bold;\">ASUNTO: AUTORIZACIÓN DE DESCUENTO POR NÓMINA.</p>\n\n  <p class=\"content-p\">\n    Yo, <strong>{{nombre_trabajador}}</strong>, mayor de edad, identificado con documento de identidad No. <strong>{{identificacion}}</strong>, en mi calidad de trabajador con el cargo de <strong>{{cargo}}</strong> de la empresa <strong>APOYO LOGÍSTICO Y OPERATIVO SAS</strong>, autorizo expresa e irrevocablemente para que, de mi salario, bonificaciones, prestaciones sociales, o de cualquier suma de dinero que se vaya generando a mi favor, me sean descontados en <strong>{{cuotas}}</strong> cuotas, por valor de <strong>{{valor}}</strong> para el pago de <strong>{{motivo}}</strong>, aun en el evento de encontrarme disfrutando de vacaciones o licencias.\n  </p>\n\n  <p class=\"content-p\">\n    Igualmente autorizo expresa e irrevocablemente a <strong>APOYO LOGÍSTICO Y OPERATIVO SAS</strong>, a descontar de mi salario, sueldo, bonificaciones, prestaciones sociales e indemnizaciones a que tengo derecho, las cuotas que se estén adeudando si se llegare a terminar mi contrato de trabajo por cualquier causa.\n  </p>\n\n  <p class=\"content-p\" style=\"margin-top: 30px;\">\n    Atentamente,\n  </p>\n\n  <div class=\"signature-container\">\n    <div class=\"signature-block\">\n      <div class=\"signature-img-wrapper\">\n        {{firma_trabajador}}\n      </div>\n      <div class=\"signature-line\">\n        Firma del Trabajador<br>\n        <span style=\"font-weight: normal; font-size: 8.5pt;\">C.C. {{identificacion}}</span>\n      </div>\n    </div>\n  </div>\n</body>\n</html>'
WHERE id_plantilla = 11 AND nombre_proceso = 'descuento_especifico';

